const profile = $('DynamoDB - Get Member Profile').first().json;

const agg = $input.first().json;

const ledger = agg.ledger_items || [];



const now = Date.now();

const twelveMonthsAgo = now - 365 * 24 * 60 * 60 * 1000;

const trailing = ledger.filter(tx => new Date(tx.transaction_date).getTime() >= twelveMonthsAgo);



const qualifyingNonDisputed = trailing.filter(tx => tx.qualifying === true && tx.dispute_status !== 'open');

const disputedTx = trailing.filter(tx => tx.dispute_status === 'open');



const currentPoints = qualifyingNonDisputed.reduce((sum, tx) => sum + Number(tx.points || 0), 0);

const openDisputes = disputedTx.length;

const disputeAmount = disputedTx.reduce((sum, tx) => sum + Number(tx.points || 0), 0);



return [{

  json: {

    member_id: profile.member_id,

    tier: profile.tier,

    threshold: Number(profile.threshold),

    tenure_years: Number(profile.tenure_years || 0),

    specialist_email: profile.specialist_email,

    member_email: profile.member_email,

    member_notification_topic_arn: profile.member_notification_topic_arn,

    current_points: currentPoints,

    open_disputes: openDisputes,

    dispute_amount: disputeAmount,

    ledger_transaction_count: trailing.length,

    review_type: 'tier-downgrade'

  }

}];

// Agent response comes into this node

const items = $input.all();



// Ledger is the source of truth for raw numbers

const ledgerData = $('Compute Points From Ledger').first().json;



return items.map(item => {

  const d = item.json;



  const toBool = (v) => v === true || v === 'true';



  const toNum = (v, fallback = null) =>

    (v === undefined || v === null || isNaN(Number(v)))

      ? fallback

      : Number(v);



  const text = d.output || d.response || d.completion || d.text || JSON.stringify(d);



  let jsonSlice = null;



  const finalJsonMatch = text.match(/FINAL_JSON:\s*(\{[\s\S]*\})\s*$/);

  if (finalJsonMatch) {

    jsonSlice = finalJsonMatch[1];

  } else {

    const start = text.indexOf('{');

    const end = text.lastIndexOf('}');

    if (start !== -1 && end !== -1 && end > start) {

      jsonSlice = text.slice(start, end + 1);

    }

  }



  if (!jsonSlice) {

    throw new Error('Agent response does not contain a valid JSON object');

  }



  let agentJson;

  try {

    agentJson = JSON.parse(jsonSlice);

  } catch (e) {

    throw new Error('Agent response JSON could not be parsed: ' + e.message);

  }



  const agentPercentBelowThreshold = toNum(agentJson.percent_below_threshold, null);

  const agentHasOpenDisputes = toBool(agentJson.has_open_disputes);

  const agentIsPlatinum = toBool(agentJson.is_platinum);

  const agentTenureWaiverEligible = toBool(agentJson.tenure_waiver_eligible);

  const agentConfidenceScore = toNum(agentJson.confidence_score, null);

  const agentIsBorderline = toBool(agentJson.is_borderline);

  const agentMeetsAutoResolve = toBool(agentJson.meets_auto_resolve);



  // Agent output is considered parseable only when

  // the key judgement fields are present.

  const agentParseOk =

    agentJson.percent_below_threshold !== undefined &&

    agentJson.confidence_score !== undefined;



  const currentPoints = Number(ledgerData.current_points);

  const threshold = Number(ledgerData.threshold);



  const recomputedPercentBelow =

    threshold > 0

      ? Number((((threshold - currentPoints) / threshold) * 100).toFixed(2))

      : 0;



  const recomputedHasDisputes = Number(ledgerData.open_disputes || 0) > 0;

  const recomputedIsPlatinum = String(ledgerData.tier || '').toLowerCase() === 'platinum';

  const recomputedTenureWaiver = Number(ledgerData.tenure_years || 0) > 3;



  let recomputedConfidenceScore;

  if (recomputedHasDisputes) {

    recomputedConfidenceScore = 0;

  } else if (recomputedPercentBelow <= 15) {

    recomputedConfidenceScore = 40;

  } else if (recomputedPercentBelow <= 20) {

    recomputedConfidenceScore = 70;

  } else {

    recomputedConfidenceScore = 95;

  }



  const agentTrustworthy =

    agentParseOk &&

    Math.abs((agentPercentBelowThreshold ?? -999) - recomputedPercentBelow) < 1;



  const percentBelowThreshold = recomputedPercentBelow;

  const hasOpenDisputes = recomputedHasDisputes;

  const isPlatinum = recomputedIsPlatinum;

  const tenureWaiverEligible = recomputedTenureWaiver;

  const confidenceScore = recomputedConfidenceScore;



  let waiverApplied = false;

  let waiverReason = null;



  if (tenureWaiverEligible) {

    waiverApplied = true;

    waiverReason = 'Tenure > 3 years - eligible for loyalty waiver consideration';

  }



  if (hasOpenDisputes) {

    waiverApplied = true;

    const disputeNote =

      `${ledgerData.open_disputes} open dispute(s) worth ` +

      `${ledgerData.dispute_amount} pts may restore qualifying balance`;

    waiverReason = waiverReason ? `${waiverReason}; ${disputeNote}` : disputeNote;

  }



  const isBorderline = (

    percentBelowThreshold < 5 ||

    hasOpenDisputes === true ||

    isPlatinum === true ||

    tenureWaiverEligible === true

  );



  const meetsAutoResolve = (

    percentBelowThreshold > 15 &&

    hasOpenDisputes === false &&

    confidenceScore >= 80

  );



  const slaDeadline = new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString();



  return {

    json: {

      // Ledger remains the base/source-of-truth data

      ...ledgerData,



      // Deterministic, ledger-derived values (always used)

      percent_below_threshold: percentBelowThreshold,

      has_open_disputes: hasOpenDisputes,

      is_platinum: isPlatinum,

      tenure_waiver_eligible: tenureWaiverEligible,

      confidence_score: confidenceScore,



      // Agent status (diagnostics only)

      agent_parse_ok: agentParseOk,

      agent_trustworthy: agentTrustworthy,



      // Agent's original judgement fields (diagnostics only)

      agent_percent_below_threshold: agentPercentBelowThreshold,

      agent_confidence_score: agentConfidenceScore,

      agent_is_borderline: agentIsBorderline,

      agent_meets_auto_resolve: agentMeetsAutoResolve,



      // Final deterministic decisions

      waiver_applied: waiverApplied,

      waiver_reason: waiverReason,

      is_borderline: isBorderline,

      meets_auto_resolve: meetsAutoResolve,



      // SLA

      sla_deadline: slaDeadline,

      review_started_at: new Date().toISOString()

    }

  };

});

